"""Generate a minimal CMakeLists.txt for openh264 (Windows, no meson) from its own meson.build source lists.

Builds one static library `openh264` = common + processing + encoder + decoder, C/C++ only (no NEON .S yet),
installs the 4 public headers to include/wels like meson does.
Usage: python -I gen_openh264_cmake.py <openh264-src> <out-dir>
"""
import os
import re
import sys

src, out = sys.argv[1], sys.argv[2]


def sources(sub):
    text = open(os.path.join(src, 'codec', sub, 'meson.build'), encoding='utf-8').read()
    m = re.search(r"cpp_sources = \[(.*?)\]", text, re.S)
    files = re.findall(r"'([^']+)'", m.group(1))
    return ['codec/%s/%s' % (sub, f) for f in files]


parts = {s: sources(s) for s in ('common', 'processing', 'encoder', 'decoder')}
for s, fl in parts.items():
    for f in fl:
        if not os.path.isfile(os.path.join(src, f)):
            sys.exit('missing source: ' + f)

inc = {
    'common': ['codec/api/wels', 'codec/common/inc'],
    'processing': ['codec/api/wels', 'codec/common/inc', 'codec/processing/interface',
                   'codec/processing/src/common', 'codec/processing/src/adaptivequantization',
                   'codec/processing/src/downsample', 'codec/processing/src/scrolldetection',
                   'codec/processing/src/vaacalc'],
    'encoder': ['codec/api/wels', 'codec/common/inc', 'codec/processing/interface',
                'codec/processing/src/common', 'codec/processing/src/adaptivequantization',
                'codec/processing/src/downsample', 'codec/processing/src/scrolldetection',
                'codec/processing/src/vaacalc', 'codec/encoder/core/inc', 'codec/encoder/plus/inc'],
    'decoder': ['codec/api/wels', 'codec/common/inc', 'codec/decoder/core/inc', 'codec/decoder/plus/inc'],
}

lines = [
    '# Generated by gen_openh264_cmake.py from openh264 v2.6.0 meson.build source lists (no asm).',
    'cmake_minimum_required(VERSION 3.16)',
    'project(openh264 LANGUAGES C CXX)',
    'set(OPENH264_SRC "%s" CACHE PATH "openh264 source tree")' % src.replace('\\', '/'),
    'add_library(openh264 STATIC)',
]
for s, fl in parts.items():
    lines.append('add_library(oh264_%s OBJECT' % s)
    lines += ['    ${OPENH264_SRC}/%s' % f for f in fl]
    lines.append(')')
    lines.append('target_include_directories(oh264_%s PRIVATE' % s)
    lines += ['    ${OPENH264_SRC}/%s' % d for d in inc[s]]
    lines.append(')')
    lines.append('target_sources(openh264 PRIVATE $<TARGET_OBJECTS:oh264_%s>)' % s)
lines += [
    'install(TARGETS openh264 ARCHIVE DESTINATION lib)',
    'install(FILES',
    '    ${OPENH264_SRC}/codec/api/wels/codec_api.h',
    '    ${OPENH264_SRC}/codec/api/wels/codec_app_def.h',
    '    ${OPENH264_SRC}/codec/api/wels/codec_def.h',
    '    ${OPENH264_SRC}/codec/api/wels/codec_ver.h',
    '    DESTINATION include/wels)',
]
os.makedirs(out, exist_ok=True)
with open(os.path.join(out, 'CMakeLists.txt'), 'w', encoding='utf-8', newline='\n') as f:
    f.write('\n'.join(lines) + '\n')
print({s: len(fl) for s, fl in parts.items()})
